ValidationRule.errorConditionFormula:
AND(
    ISCHANGED(Case_Model__c),
    NOT($Setup.Setting__c.Bypass_Validation_Rules__c),
    NOT(archive__c),

    NOT(
        AND(
            CreatedBy.LastName = 'System',
            ISPICKVAL(Origin, 'Email-Alburaq')
        )
    ),

    OR(
        TEXT(Account.PersonContact.Subscription_Model__c) = 'ila',
        TEXT(Account.PersonContact.Subscription_Model__c) = 'alburaq'
    ),

    /* EXCLUDE Relationship Termination + Sub-Type values */
    NOT(
        AND(
            ISPICKVAL(Type, "Relationship Termination"),
            OR(
                ISPICKVAL(Sub_Type__c, "Relationship Termination - By Bank"),
                ISPICKVAL(Sub_Type__c, "Relationship Termination - By Customer")
            )
        )
    )
)
